p='world/chop/axe_swing.gd'
s=open(p).read()
marker='''# The targets the swept tool can touch at all (their capsules, ChopAim.bound_of, against the swing's plane'''
add='''## (task 62 feel-2, item 4) The same swept head carried on along the arc as if nothing resisted it («как по маслу»), from the
## contact at arc angle `th0`: where its edge row first lies in a solid (th_in) and where it comes out on the far side (th_out),
## and how long the way inside is. The edge row is probed along n, ~SWEEP_GAP apart, in any of `targets` ({solid: Callable(world p)
## -> bool, thin: bool}), stepping SWEEP_STEP (the finer FINE_STEP against a thin target) and bisecting REFINE times onto both
## changes. {th_in, th_out, through (the edge left the material within `max_len` m of path), len (m inside), graze (the edge row
## never got into a solid: the contact was the cheeks' or the haft's)}. A contact whose edge row stays dry within GRAZE_DEG is a graze.
## Pure; one `solid` call per probe, <= ~(max_len / step) x 6 of them.
const SWEEP_STEP := 0.02        # m the head moves per step of the sweep
const SWEEP_GAP := 0.02         # m between the edge row's probes
const GRAZE_DEG := 12.0

static func sweep_exit(sw: Dictionary, targets: Array, th0: float, max_len := 1.0) -> Dictionary:
	var thin := false
	for tg: Dictionary in targets:
		thin = thin or bool(tg.get("thin", false))
	var step := minf(fine_step, SWEEP_STEP) if thin else SWEEP_STEP
	var radius := float(sw.radius)
	var df := step / radius
	var ei := maxf(0.5 * float(sw.edge) - probe_in, 0.0)
	var ne := clampi(ceili(2.0 * ei / SWEEP_GAP) + 1, 3, 9)
	var th := th0
	var th_in := th0
	var found := _edge_in(sw, th0, targets, ei, ne)
	if not found:
		var th_stop := th0 - deg_to_rad(GRAZE_DEG)
		var prev := th0
		th = th0 - df
		while th >= th_stop:
			if _edge_in(sw, th, targets, ei, ne):
				found = true
				th_in = _bisect(sw, prev, th, targets, ei, ne, true)
				break
			prev = th
			th -= df
		if not found:
			return {"th_in": th0, "th_out": th0, "through": false, "len": 0.0, "graze": true}
	th = th_in
	var travelled := 0.0
	var th_end := deg_to_rad(END_DEG)
	while true:
		var nxt := th - df
		if nxt < th_end or travelled + step > max_len:
			return {"th_in": th_in, "th_out": th, "through": false, "len": travelled, "graze": false}
		if not _edge_in(sw, nxt, targets, ei, ne):
			var out := _bisect(sw, th, nxt, targets, ei, ne, false)
			return {"th_in": th_in, "th_out": out, "through": true, "len": (th_in - out) * radius, "graze": false}
		th = nxt
		travelled += step
	return {}


# Any probe of the edge row at arc angle th lies in a target's solid.
static func _edge_in(sw: Dictionary, th: float, targets: Array, ei: float, ne: int) -> bool:
	var n := n_at(sw, th)
	var mid: Vector3 = sw.s + n * float(sw.radius)
	for tg: Dictionary in targets:
		var solid: Callable = tg.solid
		for i in ne:
			if solid.call(mid + n * ((float(i) / (ne - 1) * 2.0 - 1.0) * ei)):
				return true
	return false


# Between th_a (the edge row's state is `want_in` = false there for an entry, true for an exit) and th_b (the other state): the
# angle of the change, REFINE bisections, on the side that is inside.
static func _bisect(sw: Dictionary, th_a: float, th_b: float, targets: Array, ei: float, ne: int, entry: bool) -> float:
	var a := th_a
	var b := th_b
	for i in REFINE:
		var m := 0.5 * (a + b)
		if _edge_in(sw, m, targets, ei, ne) == entry:
			b = m
		else:
			a = m
	return b if entry else a


'''
assert marker in s
s=s.replace(marker, add+marker,1)
