const TUBE := Color(0.28, 0.0, 0.02, 0.55)
const TUBE_SEG := 0.06            # m of path per tube segment
const SHOVEL_THICK := 0.012       # m: half the blade's thickness
const SHOVEL_LEN := 0.2           # m of the thrust drawn into the ground
const GROUND_LEN := 0.3           # m of the arc drawn into the ground (it has no far side)
const ROCK_LEN := 0.6

var _held: HeldAxe
var _im := ImmediateMesh.new()
