## Pairs of triangles of the soup `t` (3 points each) that pass through each other without sharing a corner (a folded
## surface: Godot's CSG, Manifold, takes only non-self-intersecting solids). Tests only: every pair whose boxes meet.
static func self_crossings(t: PackedVector3Array) -> int:
	var n := t.size() / 3
	var lo: Array[Vector3] = []
	var hi: Array[Vector3] = []
	for i in n:
		lo.append(t[i * 3].min(t[i * 3 + 1]).min(t[i * 3 + 2]))
		hi.append(t[i * 3].max(t[i * 3 + 1]).max(t[i * 3 + 2]))
	var count := 0
	for i in n:
		for j in range(i + 1, n):
			if lo[i].x > hi[j].x or lo[j].x > hi[i].x or lo[i].y > hi[j].y or lo[j].y > hi[i].y \\
					or lo[i].z > hi[j].z or lo[j].z > hi[i].z:
				continue
			var shared := false
			for a in 3:
				for b in 3:
					if t[i * 3 + a].distance_squared_to(t[j * 3 + b]) < 1e-14:
						shared = true
			if shared:
				continue
			var hit := false
			for k in 3:
				if _seg_tri(t[i * 3 + k], t[i * 3 + (k + 1) % 3], t, j * 3) or _seg_tri(t[j * 3 + k], t[j * 3 + (k + 1) % 3], t, i * 3):
					hit = true
					break
			if hit:
