## Manifold, takes only non-self-intersecting solids). Tests only: every pair whose boxes meet; two triangles that share
## an edge, lie in one plane (within 1e-9 m) or only touch are not a crossing; `pairs_out` gets the pairs.
static func self_crossings(t: PackedVector3Array, pairs_out: Array = []) -> int:
	var n := t.size() / 3
	var lo: Array[Vector3] = []
	var hi: Array[Vector3] = []
	for i in n:
		lo.append(t[i * 3].min(t[i * 3 + 1]).min(t[i * 3 + 2]))
		hi.append(t[i * 3].max(t[i * 3 + 1]).max(t[i * 3 + 2]))
	var count := 0
	for i in n:
		for j in range(i + 1, n):
			if lo[i].x > hi[j].x or lo[j].x > hi[i].x or lo[i].y > hi[j].y or lo[j].y > hi[i].y \\
					or lo[i].z > hi[j].z or lo[j].z > hi[i].z:
				continue
			var shared := 0
			for a in 3:
				for b in 3:
					if t[i * 3 + a].distance_squared_to(t[j * 3 + b]) < 1e-14:
						shared += 1
			if shared >= 2:
				continue
			if _tri_tri(t, i * 3, j * 3):
				count += 1
				pairs_out.append(Vector2i(i, j))
	return count


# Möller: do triangles (t[a..a+2]) and (t[b..b+2]) cross, neither lying in the other's plane, their overlap along the
# common line longer than 1e-9 m.
static func _tri_tri(t: PackedVector3Array, a: int, b: int) -> bool:
	var na := (t[a + 1] - t[a]).cross(t[a + 2] - t[a])
	var nb := (t[b + 1] - t[b]).cross(t[b + 2] - t[b])
	var la := na.length()
	var lb := nb.length()
	if la < 1e-12 or lb < 1e-12:
		return false
	na /= la
	nb /= lb
	var db := [na.dot(t[b] - t[a]), na.dot(t[b + 1] - t[a]), na.dot(t[b + 2] - t[a])]
	if (db[0] > 1e-9 and db[1] > 1e-9 and db[2] > 1e-9) or (db[0] < -1e-9 and db[1] < -1e-9 and db[2] < -1e-9):
		return false
	if absf(db[0]) <= 1e-9 and absf(db[1]) <= 1e-9 and absf(db[2]) <= 1e-9:
		return false
	var da := [nb.dot(t[a] - t[b]), nb.dot(t[a + 1] - t[b]), nb.dot(t[a + 2] - t[b])]
	if (da[0] > 1e-9 and da[1] > 1e-9 and da[2] > 1e-9) or (da[0] < -1e-9 and da[1] < -1e-9 and da[2] < -1e-9):
		return false
	if absf(da[0]) <= 1e-9 and absf(da[1]) <= 1e-9 and absf(da[2]) <= 1e-9:
		return false
	var dir := na.cross(nb)
	if dir.length() < 1e-9:
		return false
	var ia := _span(t, a, da, dir)
	var ib := _span(t, b, db, dir)
	return minf(ia.y, ib.y) - maxf(ia.x, ib.x) > 1e-9


# The stretch (min, max of the position along `dir`) where the triangle at t[o..o+2] (distances d to the other plane) meets that plane.
static func _span(t: PackedVector3Array, o: int, d: Array, dir: Vector3) -> Vector2:
	var lo := INF
	var hi := -INF
	for i in 3:
		var j := (i + 1) % 3
		if absf(d[i]) <= 1e-9:
			var s := t[o + i].dot(dir)
			lo = minf(lo, s)
			hi = maxf(hi, s)
		if (d[i] > 1e-9 and d[j] < -1e-9) or (d[i] < -1e-9 and d[j] > 1e-9):
			var p: Vector3 = t[o + i].lerp(t[o + j], d[i] / (d[i] - d[j]))
			var s2 := p.dot(dir)
			lo = minf(lo, s2)
			hi = maxf(hi, s2)
	return Vector2(lo, hi)
