static func _cup(r: float, h: float, w: float, b: float) -> CpuMesh:
	var prof: Array[Vector2] = [Vector2(0.0, 0.0), Vector2(r, 0.0)]
	for k in range(1, 7):
		prof.append(Vector2(r, h * k / 6.0))
	for k in range(0, 7):
		prof.append(Vector2(r - w, h - (h - b) * k / 6.0))
	prof.append(Vector2(0.0, b))
	var sides := 16
	var v := PackedVector3Array()
	for pt: Vector2 in prof:
		for i in sides:
			var a := TAU * i / sides
			v.append(Vector3(cos(a) * pt.x, pt.y, sin(a) * pt.x))
	var idx := PackedInt32Array()
	for j in prof.size() - 1:                    # the profile runs counter-clockwise (r right, y up); the axis closes it
		var d := prof[j + 1] - prof[j]
		var out := Vector2(d.y, -d.x).normalized()   # outward: right of the direction of travel
		for i in sides:
			var i2 := (i + 1) % sides
			var am := TAU * (i + 0.5) / sides
			var o := Vector3(out.x * cos(am), out.y, out.x * sin(am))
			var q := [j * sides + i, j * sides + i2, (j + 1) * sides + i2, (j + 1) * sides + i]
			for t: Array in [[q[0], q[1], q[2]], [q[0], q[2], q[3]]]:
